<script setup lang="ts">
/**
 * Picks one value from a few options that are all visible (`design/components/radio.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/radio.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/radio-group'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { agentMember, roveRadio, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/radio-group.module.css'

export type RadioOrientation = NonNullable<RadioGroupProps['orientation']>

export interface RadioOption {
  value: string
  label: string
  disabled?: boolean
}

export interface RadioGroupProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField, because the group's question is the field's label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  name?: string
  options: RadioOption[]
  /**
   * Horizontal is for three short labels at most. Guidance, not enforcement.
   */
  orientation?: 'horizontal' | 'vertical'
  value?: string
}

defineOptions({ name: 'RadioGroup', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<RadioGroupProps>(), {
  ariaRequired: undefined,
  disabled: false,
  invalid: false,
  orientation: 'vertical',
})
const emit = defineEmits<{ change: [value: string] }>()
const uid = useId()
const group = useTemplateRef<HTMLElement>('group')
const documentDirection = useDirection(() => group.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    value: props.value,
    defaultValue: props.defaultValue,
    disabled: props.disabled,
    name: props.name,
    orientation: props.orientation,
    onValueChange: (details) => {
      emit('change', details.value ?? '')
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const stop = computed(
  () =>
    api.value.value ??
    props.options.find((option) => !(props.disabled || option.disabled === true))?.value,
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'RadioGroup',
    element: () => group.value,
    state: () => ({
      value: api.value.value ?? null,
      options: props.options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => value !== api.value.value && api.value.setValue(value),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    ref="group"
    :class="styles.group"
    role="radiogroup"
    :id="id"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-required="ariaRequired"
    :aria-invalid="invalid ? true : undefined"
    :data-orientation="orientation"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-required="ariaRequired ? '' : undefined"
    data-member="radio-group"
  >
    <template v-for="option in options" :key="option.value">
      <!-- row -->
      <label :class="styles.row">
        <!-- radio -->
        <button
          :class="styles.circle"
          type="button"
          role="radio"
          :value="option.value"
          :aria-checked="api.value === option.value"
          :disabled="disabled || option.disabled === true"
          :tabindex="option.value === stop ? 0 : -1"
          :data-state="api.value === option.value ? 'checked' : 'unchecked'"
          :data-disabled="disabled || option.disabled === true ? '' : undefined"
          @click="api.setValue(option.value)"
          @keydown="
            $event.key === 'Enter'
              ? $event.preventDefault()
              : roveRadio($event, (next) => api.setValue(next))
          "
        >
          <!-- dot -->
          <span v-if="api.value === option.value" :class="styles.dot" data-state="checked" />
        </button>
        <span :class="styles.label">
          {{ option.label }}
        </span>
      </label>
    </template>
  </div>
  <input
    v-if="name !== undefined"
    type="hidden"
    :name="name"
    :value="api.value ?? ''"
    :disabled="disabled"
  />
</template>
